import json

# Load all JSON files and check for corporate income taxes monthly data
files = [
    '/app/resources/treasury_bulletin_2021_03.json',
    '/app/resources/treasury_bulletin_2021_06.json',
    '/app/resources/treasury_bulletin_2021_09.json',
    '/app/resources/treasury_bulletin_2021_12.json'
]

for f in files:
    print(f'\\n=== {f} ===')
    with open(f, 'r') as fp:
        data = json.load(fp)

    # Look for tables with 'Source' and 'Corporate'
    def search(obj, path=''):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if 'corporate' in str(k).lower():
                    print(f'Found key: {path}.{k}')
                search(v, f'{path}.{k}' if path else k)
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                search(item, f'{path}[{i}]')

    search(data)
